/**
 * config/ui/tokens.json -> packages/ui/src/kit/tokens.css (custom properties).
 * Run by `pnpm build` and `pnpm dev`; the generated file is committed and a unit test fails when it drifts.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export interface Tokens {
  manifest: { themeColor: string; backgroundColor: string };
  root: Record<string, string>;
  themes: Record<string, Record<string, string>>;
  contrast: Record<string, Record<string, string>>;
  reducedMotion: Record<string, string>;
}

const here = path.dirname(fileURLToPath(import.meta.url));
export const TOKENS_JSON = path.resolve(here, '../../../config/ui/tokens.json');
export const TOKENS_CSS = path.resolve(here, '../src/kit/tokens.css');

function block(selector: string, vars: Record<string, string>): string {
  const lines = Object.entries(vars).map(([k, v]) => `  --dv-${k}: ${v};`);
  return `${selector} {\n${lines.join('\n')}\n}\n`;
}

export function renderTokensCss(tokens: Tokens): string {
  const parts = ['/* Generated by packages/ui/scripts/build-tokens.ts from config/ui/tokens.json. Do not edit. */\n'];
  parts.push(block(':root', tokens.root));
  for (const [name, vars] of Object.entries(tokens.themes)) parts.push(block(`[data-theme='${name}']`, vars));
  for (const [name, vars] of Object.entries(tokens.contrast)) parts.push(block(`[data-contrast='${name}']`, vars));
  parts.push(block(`[data-reduced-motion='true']`, tokens.reducedMotion));
  parts.push(`@media (prefers-reduced-motion: reduce) {\n${block(':root', tokens.reducedMotion).replace(/^/gm, '  ').trimEnd()}\n}\n`);
  return parts.join('\n');
}

export function readTokens(): Tokens {
  return JSON.parse(readFileSync(TOKENS_JSON, 'utf8')) as Tokens;
}

function main(): void {
  writeFileSync(TOKENS_CSS, renderTokensCss(readTokens()));
  console.log(`tokens: wrote ${path.relative(process.cwd(), TOKENS_CSS)}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
